/* @autogenerated */
package net.civeira.phylax.feature.oauth.delegatelogin.application.listener;

import java.util.Objects;
import java.util.Optional;

import jakarta.enterprise.context.ApplicationScoped;
import jakarta.enterprise.event.Observes;
import lombok.RequiredArgsConstructor;
import net.civeira.phylax.common.exception.ConstraintException;
import net.civeira.phylax.feature.identity.tenantloginprovider.domain.TenantLoginProvider;
import net.civeira.phylax.feature.identity.tenantloginprovider.domain.gateway.TenantLoginProviderQueryRepositoryGateway;
import net.civeira.phylax.feature.identity.user.domain.User;
import net.civeira.phylax.feature.identity.user.domain.gateway.UserQueryRepositoryGateway;
import net.civeira.phylax.feature.identity.userfederatedidentity.application.usecase.create.UserFederatedIdentityCreateCheck;
import net.civeira.phylax.feature.identity.userfederatedidentity.application.usecase.update.UserFederatedIdentityUpdateCheck;
import net.civeira.phylax.feature.identity.userfederatedidentity.domain.UserFederatedIdentity;
import net.civeira.phylax.feature.identity.userfederatedidentity.domain.gateway.UserFederatedIdentityQueryRepositoryGateway;
import net.civeira.phylax.feature.identity.userfederatedidentity.domain.valueobject.LoginProviderVO;
import net.civeira.phylax.feature.identity.userfederatedidentity.domain.valueobject.UserVO;

/**
 * Keeps federated identity links within one tenant.
 *
 * Responsibilities: - Reject, on create and update through the Access API, a link whose login
 * provider belongs to another tenant than the user.
 *
 * Design notes: - The generated API only checks that the user is visible to the caller. Without
 * this check an administrator could link a provider of another tenant: it would not grant access
 * (the login only opens accounts of the provider's tenant), but the unique index would reserve the
 * subject and lock out the real user of that tenant.
 */
@ApplicationScoped
@RequiredArgsConstructor
public class FederatedIdentityWithinOneTenant {
  private final UserQueryRepositoryGateway users;
  private final TenantLoginProviderQueryRepositoryGateway providers;
  private final UserFederatedIdentityQueryRepositoryGateway identities;

  /**
   * Checks a new link.
   *
   * @param check create check event
   */
  public void onCreate(@Observes UserFederatedIdentityCreateCheck check) {
    verify(check.getInput().getUser().map(UserVO::getUserUid),
        check.getInput().getLoginProvider().map(LoginProviderVO::getLoginProviderUid));
  }

  /**
   * Checks a modified link, completing missing fields from the stored one.
   *
   * @param check update check event
   */
  public void onUpdate(@Observes UserFederatedIdentityUpdateCheck check) {
    Optional<UserFederatedIdentity> original =
        identities.retrieve(check.getReference().getUid(), Optional.empty());
    verify(
        check.getInput().getUser().map(UserVO::getUserUid)
            .or(() -> original.map(UserFederatedIdentity::getUserUid)),
        check.getInput().getLoginProvider().map(LoginProviderVO::getLoginProviderUid)
            .or(() -> original.map(UserFederatedIdentity::getLoginProviderUid)));
  }

  private void verify(Optional<String> userUid, Optional<String> providerUid) {
    if (userUid.isEmpty() || providerUid.isEmpty()) {
      return;
    }
    Optional<String> userTenant = users.retrieve(userUid.get(), Optional.empty())
        .map(User::getTenant).map(tenant -> tenant.getUid());
    Optional<String> providerTenant = providers.retrieve(providerUid.get(), Optional.empty())
        .map(TenantLoginProvider::getTenant).map(tenant -> tenant.getUid());
    if (userTenant.isPresent() && providerTenant.isPresent()
        && !Objects.equals(userTenant.get(), providerTenant.get())) {
      throw new ConstraintException("The login provider belongs to another tenant",
          "different-tenant", "loginProvider", providerUid.get());
    }
  }
}
